mapper.select:
SELECT COUNT(*)
FROM store
WHERE store_status = #{storeStatus}

mapper.update:
UPDATE
    store
SET
    store_status = #{storeUpdateStatusDTO.status}
WHERE
    store_code = #{storeCode}

mapper.delete:
DELETE FROM store_like
WHERE
    store_code = #{storeCode}
AND
    user_code = #{userCode}
